INSERT INTO pages(slug,title,meta_description,content_html) VALUES
('about','About INFOROVA','About the INFOROVA publication','<h2>About us</h2><p>INFOROVA is an independent information website focused on useful, readable and organized content.</p><p>We aim to publish clear articles across jobs, exams and practical topics.</p>'),
('contact','Contact','Contact INFOROVA','<h2>Contact</h2><p>For editorial or website questions, contact the site administrator through the official contact channel published on this website.</p>'),
('privacy-policy','Privacy Policy','INFOROVA privacy policy','<h2>Privacy Policy</h2><p>We may process basic technical information such as browser, device and server logs to operate and secure the website. Advertising and analytics providers may use cookies or similar technologies according to their own policies.</p><p>Do not submit sensitive personal information through public forms.</p>'),
('terms','Terms of Use','Terms of use for INFOROVA','<h2>Terms of Use</h2><p>Content is provided for general informational purposes. Verify important dates, eligibility requirements and official notices with the relevant authority.</p>'),
('disclaimer','Disclaimer','INFOROVA disclaimer','<h2>Disclaimer</h2><p>INFOROVA is an independent publication and is not an official government authority unless explicitly stated. Information can change; readers should check primary sources before making decisions.</p>'),
('cookie-policy','Cookie Policy','INFOROVA cookie policy','<h2>Cookie Policy</h2><p>This site may use essential cookies for functionality and optional cookies from advertising or analytics services where configured.</p>');
