INSERT INTO articles(category_id,title,slug,excerpt,content_html,status,published_at) VALUES
(1,'How to Read a Government Job Notice Correctly','how-to-read-a-government-job-notice','A simple guide to checking eligibility, dates, documents and application instructions.','<p>Government job notices can contain many details. Start by checking the official notice date and application deadline.</p><h2>Check the essentials</h2><ul><li>Eligibility and age requirements</li><li>Application opening and closing dates</li><li>Required documents</li><li>Official application website</li></ul><p>Always verify the final information from the issuing authority.</p>','published',NOW()),
(2,'Exam News: What to Check Before Applying','exam-news-what-to-check-before-applying','Key items to verify before submitting an exam application.','<p>Before submitting an application, confirm the official notice, fee information, deadlines and required documents.</p><h2>Keep a checklist</h2><p>Save the official notice and record the important dates in your calendar.</p>','published',NOW()),
(3,'A Practical Weekly Exam Preparation Plan','practical-weekly-exam-preparation-plan','A flexible study structure for reviewing topics, practicing questions and tracking progress.','<p>A useful plan balances learning, practice and revision.</p><h2>Weekly structure</h2><p>Choose a small number of topics, practice questions regularly and reserve time to review mistakes.</p>','published',NOW());
