CREATE DATABASE IF NOT EXISTS inforova CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE inforova;
CREATE TABLE admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','blocked') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,description VARCHAR(500) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE articles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,excerpt VARCHAR(500) NOT NULL,content_html MEDIUMTEXT NOT NULL,status ENUM('draft','published') NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),KEY idx_articles_status_date(status,published_at),KEY idx_articles_category(category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(140) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,meta_description VARCHAR(500) NOT NULL DEFAULT '',content_html MEDIUMTEXT NOT NULL,status ENUM('draft','published') NOT NULL DEFAULT 'published') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
